'use strict';
const $ = id => document.getElementById(id);
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text = value => value == null || value === '' ? '未知' : String(value);
const typeLabels={measured_vps:'VPS 实测记录',advertised_plan:'商品套餐宣称',review_configuration_version:'配置阶段对照',measured_host:'家用主机实测'};
const categoryLabels={review:'测评',stock_notice:'补货 / 套餐',tool_release:'工具资料',multi_vps_review:'多对象对照',network_followup:'网络复测',home_server_benchmark:'家用主机',benchmark_comparison:'基准对照',network_incident:'网络异常',link_only:'外部报告资料',upgrade_comparison:'升级阶段',tuning_comparison:'调优对照',connectivity_test:'连通性测试'};
const periodLabels={monthly:'月',quarterly:'季',semiannual:'半年',yearly:'年',annual:'年',two_years:'两年',biennial:'两年',three_years:'三年',triennial:'三年'};
const filterNames={itemType:'资料类型',vendor:'商家',cpu:'CPU 核数',memory:'内存 GB',disk:'硬盘 G',cpuModel:'CPU 型号',diskType:'硬盘类型',country:'国家 / 地区',city:'城市',route:'线路标签',routeSource:'线路依据',currency:'币种',period:'计费周期',priceKind:'价格类型',maxPrice:'价格上限',benchmark:'CPU 跑分桶'};
const multiFields=['itemType','vendor','cpuModel','diskType','country','city','route','routeSource','currency','period','priceKind','benchmark'];
const numericFields=['cpu','memory','disk','maxPrice'];
const fields=Object.keys(filterNames);
const state={data:null,items:[],posts:[],mode:'items',page:1,pageSize:15,filtered:[],detailFromApp:false,multi:Object.fromEntries(multiFields.map(k=>[k,[]])),scoreRanges:{},buckets:[],optionLabels:{}};
const isKnownNumber=value=>typeof value==='number'&&Number.isFinite(value);
const getLocation=i=>[i.location?.country,i.location?.city||i.location?.region].filter(Boolean).join(' · ');
function getFilterCity(item){if(item.skillReview)return skillHistoricalFact(item,'city')?.value||null;return item.location?.city||item.location?.region||null;}
const normalizeDiskType=value=>/NVMe/i.test(value||'')?'NVMe':/SSD/i.test(value||'')?'SSD':/HDD/i.test(value||'')?'HDD':'';
const getDiskType=i=>{const fresh=skillFact(i,'disk_type');if(fresh)return fresh.filterEligible?normalizeDiskType(fresh.value):'';return normalizeDiskType(i.configuration?.diskUnit||'');};
const priceKindLabels={regular:'常规价格',first_term:'首期',renewal:'续费',transfer:'转让',setup:'开通费',one_time:'一次性',promotional:'促销价',list_price:'原价',first_period_offer:'首期优惠',secondary_market_purchase:'二手成交价',secondary_market_premium:'二手溢价',unspecified:'未注明首期 / 续费',unknown:'价格类型未知'};
const metricLabels={single_core:'单核',multi_core:'多核',single:'单核',multi:'多核',events_per_second:'每秒事件',events_per_sec:'每秒事件',cpu_score:'CPU 分数'};
function capacity(value,unit){if(!isKnownNumber(value)||!unit)return null;const u=unit.toUpperCase();if(/^(?:T|TB|TIB)/.test(u))return value*1024;if(/^(?:G|GB|GIB)/.test(u))return value;if(/^(?:M|MB|MIB)/.test(u))return value/1024;return null;}
function strictGreater(value,threshold){if(threshold===''||threshold==null)return true;const n=Number(threshold);return isKnownNumber(value)&&Number.isFinite(n)&&n>=0&&value>n;}
function asArray(value){return Array.isArray(value)?value:value?[value]:[];}
function multiMatch(value,choices){const selected=asArray(choices);return !selected.length||selected.includes(value==null||value===''?'unknown':String(value));}
function parsePriceText(raw,options={}){
 const input=String(raw||'').trim();const hint=isKnownNumber(options.amountHint)?options.amountHint:null;
 if(hint==null&&/(?:^|\s)-\s*\d/.test(input))return {amount:null,currency:null,currencyBasis:null};
 if(!input&&hint==null)return {amount:null,currency:null,currencyBasis:null};
 if(!options.priceContext&&hint==null)return {amount:null,currency:null,currencyBasis:null};
 if(hint==null&&/型号|CPU|EPYC|GHz|内存|硬盘|跑分|Geekbench|Sysbench|\b\d+(?:\.\d+)?\s*(?:GB|GiB|MB|TB|核|线程)/i.test(input))return {amount:null,currency:null,currencyBasis:null};
 const amount=hint??Number((input.match(/(?:^|[^\d.])(\d+(?:\.\d+)?)(?=\s*(?:刀|[Oo](?![A-Za-z])|欧|美元|美金|元|USD|EUR|CNY|RMB|CAD|JPY|[\/月年季]|$))/i)||input.match(/(?:USD|EUR|CNY|RMB|CAD|JPY|US\$|CA\$|\$|€|¥|￥)\s*(\d+(?:\.\d+)?)/i)||[])[1]);
 if(!Number.isFinite(amount)||amount<0)return {amount:null,currency:null,currencyBasis:null};
 let currency=options.explicitCurrency||null,basis=currency?'原文明确币种':null;
 if(!currency){if(/\bCAD\b|CA\$|加元/i.test(input)){currency='CAD';basis='原文明确币种';}else if(/\bJPY\b|日元/i.test(input)){currency='JPY';basis='原文明确币种';}else if(/\b(?:CNY|RMB)\b|人民币|[¥￥]|\d\s*元/i.test(input)){currency='CNY';basis='原文明确币种';}else if(/\bEUR\b|€|欧|\d(?:\.\d+)?\s*[Oo](?=$|[^A-Za-z])/i.test(input)){currency='EUR';basis=/\bEUR\b|€/i.test(input)?'原文明确币种':'欧 / O 按站点约定识别为欧元';}else if(/\bUSD\b|US\$|\$|美元|美金/i.test(input)){currency='USD';basis='原文明确币种';}else if(/刀/.test(input)){currency='USD';basis='刀按站点约定识别为美元';}else{currency='USD';basis='默认美元（价格未注明币种）';}}
 return {amount,currency,currencyBasis:basis};
}
function normalizePriceKind(kind){return ({first:'first_term',initial:'first_term',first_period:'first_term',recurring:'regular',standard:'regular',resale:'transfer',first_payment:'first_term'}[kind]||kind||'unspecified');}
const inferenceLabels={explicit_currency:'原文明确币种',dao_usd_by_user_rule:'刀按站点约定识别为美元',o_euro_by_user_rule:'O / o / 欧按站点约定识别为欧元',o_eur_by_user_rule:'O / o 按站点约定识别为欧元',eur_by_user_rule:'O / o / 欧按站点约定识别为欧元',euro_by_user_rule:'欧按站点约定识别为欧元',inferred_by_user_rule:'默认美元（价格未注明币种）',ambiguous_currency:'币种未确认',actual_paid_amount_unknown:'实际支付金额未知',price_semantics_unconfirmed:'是否为价格尚未确认',unresolved_currency_shorthand:'原币种缩写未确认'};
function priceRecords(item){
 if(Array.isArray(item.priceObservations)){
  if(!item.priceObservations.length)return [{amount:null,currency:null,billingPeriod:null,priceKind:'unknown',raw:item.price?.raw||'',currencyBasis:null,filterEligible:false}];
  return item.priceObservations.map(p=>({...p,raw:p.raw||p.rawText||p.evidence||item.price?.raw||'',priceKind:normalizePriceKind(p.priceKind),currencyBasis:p.currencyBasis||inferenceLabels[p.inference]||p.inference||null}));
 }
 const p=item.price||{};const parsed=parsePriceText(p.raw,{priceContext:true,amountHint:p.amount,explicitCurrency:p.currency});return [{...p,...parsed,raw:p.raw||'',priceKind:'unspecified'}];
}
function basePrimaryPrice(item){const rows=priceRecords(item);return rows.find(p=>p.isPrimary===true&&p.amount!=null&&p.priceKind!=='transfer')||rows.find(p=>['regular','renewal'].includes(p.priceKind)&&p.amount!=null)||rows.find(p=>p.priceKind==='first_term'&&p.amount!=null)||rows.find(p=>p.priceKind!=='transfer'&&p.priceKind!=='setup'&&p.amount!=null)||rows.find(p=>p.priceKind!=='transfer')||null;}
function primaryPrice(item){return displayedPrice(item);}
function benchmarks(item){return asArray(item.cpuBenchmarks).filter(b=>isKnownNumber(b.score));}
function stableParams(value){if(!value)return '';if(typeof value==='string')return value;return Object.keys(value).sort().map(k=>`${k}=${typeof value[k]==='object'?JSON.stringify(value[k]):value[k]}`).join('; ');}
function benchmarkKey(b){const version=b.majorVersion??b.version;if(b.comparisonEligible===false)return null;if(!version||/unknown|未知|unspecified/i.test(String(version)))return null;return b.comparisonKey||[b.tool||b.benchmark,String(version),b.metric,b.threads??'',b.unit||'score',stableParams(b.parameters)].join('|');}
function benchmarkLabel(b){const ver=b.majorVersion??b.version;return `${b.tool||b.benchmark||'CPU 测试'} ${ver||'版本未知'} · ${b.tool==='Sysbench'&&['single','multi'].includes(b.metric)?(b.metric==='single'?'单线程':'多线程'):(metricLabels[b.metric]||b.metric||'指标未知')}${b.threads!=null?` · ${b.threads} 线程`:''}${b.unit&&b.unit!=='score'?` · ${b.unit}`:''}`;}
function currentFilters(){return {...Object.fromEntries(numericFields.map(id=>[id,$(id).value.trim()])),...state.multi,scoreRanges:state.scoreRanges,cpuOp:$('cpuOp')?.value||'>',memoryOp:$('memoryOp')?.value||'>',diskOp:$('diskOp')?.value||'>'};}
function filterActive(f,key){return Array.isArray(f[key])?f[key].length>0:f[key]!==''&&f[key]!=null;}
function legacyMatchItem(item,f,query=''){
 const c=item.configuration||{},n=item.network||{};
 if(query&&!([item.label,item.vendor,item.product,item.itemId,item.postId,item.sourceUrl,c.cpuModel,item.summary,getLocation(item),...(n.filterRouteTags||[])].join(' ').toLowerCase().includes(query.toLowerCase())))return false;
 if(!multiMatch(item.itemType,f.itemType)||!multiMatch(item.vendor,f.vendor)||!multiMatch(c.cpuModel,f.cpuModel)||!multiMatch(getDiskType(item),f.diskType)||!multiMatch(item.location?.country,f.country)||!multiMatch(getFilterCity(item),f.city))return false;
 if(!thresholdPass(c.vcpu,f.cpu,f.cpuOp)||!thresholdPass(capacity(c.memoryValue,c.memoryUnit),f.memory,f.memoryOp)||!thresholdPass(capacity(c.diskValue,c.diskUnit),f.disk,f.diskOp))return false;
 const sources=asArray(f.routeSource),tagChoices=asArray(f.route);const tags=!sources.length||sources.length===2?n.filterRouteTags||[]:sources[0]==='reported'?n.reportedRouteTags||[]:n.claimedRouteTags||[];
 if(tagChoices.length&&!tagChoices.some(t=>t==='unknown'?!tags.length:tags.includes(t)))return false;
 if(sources.length&&!tags.length)return false;
 const currency=asArray(f.currency),period=asArray(f.period),kind=asArray(f.priceKind),max=f.maxPrice;
 if(currency.length||period.length||kind.length||(max!==''&&max!=null)){
  if(max!==''&&max!=null&&(currency.length!==1||period.length!==1||currency[0]==='unknown'||period[0]==='unknown'))return false;
  if(!priceRecords(item).some(p=>(p.filterEligible!==false||(currency.length===1&&currency[0]==='unknown'&&!period.length&&!kind.length&&(max===''||max==null)))&&multiMatch(p.currency,currency)&&multiMatch(p.billingPeriod,period)&&multiMatch(p.priceKind,kind)&&((max===''||max==null)||isKnownNumber(p.amount)&&p.priceKind!=='transfer'&&p.priceKind!=='setup'&&p.amount<=Number(max))))return false;
 }
 const chosen=asArray(f.benchmark);if(chosen.length&&!benchmarks(item).some(b=>{const key=benchmarkKey(b);if(b.isPrimary===false||!key||!chosen.includes(key))return false;const range=f.scoreRanges?.[key];return !range||b.score>=range.min&&b.score<=range.max;}))return false;
 return true;
}
function matchItem(item,f,query=''){return skillCapacityThresholdsMatch(item,f)&&legacyMatchItem(item,f,query)&&matchWorkbench(item,f);}
function safeSource(url){try{const u=new URL(url);return u.protocol==='https:'&&u.hostname==='www.nodeseek.com'&&/^\/post-\d+-1$/.test(u.pathname)?u.href:'#';}catch{return '#';}}
function badge(item){return `<span class="badge ${escapeHTML(item.itemType)}">${escapeHTML(typeLabels[item.itemType]||item.itemType)}</span>`;}
function routes(item){const n=item.network||{};const tags=[...(n.reportedRouteTags||[]).map(t=>({tag:t,type:'reported'})),...(n.claimedRouteTags||[]).map(t=>({tag:t,type:'claimed'}))];return tags.length?tags.slice(0,4).map(t=>`<span class="route-tag ${t.type}" title="${t.type==='reported'?'报告脚本标签，非独立验证':'产品或作者宣称'}">${escapeHTML(t.tag)} <span>${t.type==='reported'?'报告':'宣称'}</span></span>`).join('')+(tags.length>4?`<span class="route-tag">+${tags.length-4}</span>`:''):'<span class="unknown cpu-model">线路未知</span>';}
function capacityText(value,unit){return value==null?'未知':`${value} ${unit||'单位未知'}`;}
function dateLabel(item){const dates=item.testedAt?.datesBeijing||[];return dates.length?`报告时间 ${escapeHTML(dates[dates.length-1])} 北京`:'测试时间 / 时区未完整确认';}
function itemCard(item){const c=item.configuration||{}, post=state.posts.find(p=>p.postId===item.postId), unavailable=post?.evidenceAvailability?.unavailableImageReferencesAtCollection||0;return `<article class="result-card" data-item="${escapeHTML(item.itemId)}"><div class="card-titlebar"><div class="card-heading"><div class="vendor">${escapeHTML(item.vendor||'商家未知')}</div><button class="title-button" data-detail="item:${escapeHTML(item.itemId)}">${escapeHTML(item.product||item.label)}</button></div>${badge(item)}</div><div class="card-grid"><div><div class="spec-values"><strong>${c.vcpu==null?'<span class="unknown">核数未知</span>':`${escapeHTML(c.vcpu)}<span>核</span>`}</strong><strong>${c.memoryValue==null?'<span class="unknown">内存未知</span>':`${escapeHTML(c.memoryValue)}<span>${escapeHTML(c.memoryUnit||'单位未知')} RAM</span>`}</strong><strong>${c.diskValue==null?'<span class="unknown">硬盘未知</span>':`${escapeHTML(c.diskValue)}<span>${escapeHTML(c.diskUnit||'单位未知')}</span>`}</strong></div><div class="cpu-model">${escapeHTML(c.cpuModel||'CPU 型号未注明')}</div></div><div class="network-block"><div class="location-name ${getLocation(item)?'':'unknown'}">${escapeHTML(getLocation(item)||'地区未知')}</div><div class="route-tags">${routes(item)}</div></div><div class="price-block"><div class="price-main">${priceText(primaryPrice(item))}${primaryPrice(item)&&monthlyValue(primaryPrice(item))!=null?`<span class="monthly-value">≈ ${primaryPrice(item).currency} ${monthlyValue(primaryPrice(item)).toFixed(2)} / 月（折算）</span>`:''}</div><div class="time-label">${dateLabel(item)}</div></div></div>${scoreCard(item)}${skillCapacityNote(item)?`<p class="field-help">${escapeHTML(skillCapacityNote(item))}</p>`:''}<div class="card-bottom"><p title="${escapeHTML(c.basis||'配置依据未明确')}">#${escapeHTML(item.postId)} · ${item.itemType==='advertised_plan'?'历史标价，非性能实测':c.basis?'配置依据见详情':'配置待补'}${unavailable?` · ${unavailable} 张图未读到`:''}</p><button class="detail-link" data-detail="item:${escapeHTML(item.itemId)}">查看事实与简评</button></div></article>`;}
function postCard(post){return `<article class="result-card" data-post="${escapeHTML(post.postId)}"><div class="card-titlebar"><div class="card-heading"><div class="vendor">NODESEEK / #${escapeHTML(post.postId)}</div><button class="title-button" data-detail="post:${escapeHTML(post.postId)}">${escapeHTML(post.label)}</button></div><span class="badge">${escapeHTML(categoryLabels[post.category]||post.category)}</span></div><p class="post-summary">${escapeHTML(post.summary)}</p><div class="card-bottom"><p>${post.items.length?`${post.items.length} 条测试对象 / 套餐`:'资料帖 · 无独立测试对象'} · ${post.evidenceAvailability?.unavailableImageReferencesAtCollection?`${post.evidenceAvailability.unavailableImageReferencesAtCollection} 张图未读到`:'仅公开事实与简评'}</p><button class="detail-link" data-detail="post:${escapeHTML(post.postId)}">打开资料</button></div></article>`;}
function multiControl(id,options,unknown=false){
 const unique=new Map();for(const entry of options){const opt=typeof entry==='string'?{value:entry,label:entry}:entry;if(opt.value!=null&&opt.value!=='')unique.set(String(opt.value),opt.label||String(opt.value));}
 if(unknown)unique.set('unknown','未知 / 未注明');state.optionLabels[id]=Object.fromEntries(unique);
 const list=[...unique.entries()];$(id).innerHTML=`<details class="multi-picker"><summary><span>${escapeHTML(filterNames[id])}</span><strong data-multi-summary="${id}">不限</strong></summary><div class="multi-body">${list.length>7?`<input class="multi-search" data-search-options="${id}" type="search" placeholder="搜索选项" aria-label="搜索${escapeHTML(filterNames[id])}选项">`:''}<div class="multi-options" role="group" aria-label="${escapeHTML(filterNames[id])}多选">${list.length?list.map(([value,label])=>`<label class="check-option" data-option-label="${escapeHTML(label.toLowerCase())}"><input type="checkbox" value="${escapeHTML(value)}" data-multi="${id}"><span>${escapeHTML(label)}</span></label>`).join(''):'<p class="filter-note">暂无可识别数据</p>'}</div><button class="text-button" type="button" data-clear="${id}">清空本组</button></div></details>`;
}
function updateMultiSummary(id){const selected=state.multi[id];const el=document.querySelector(`[data-multi-summary="${id}"]`);if(el)el.textContent=selected.length?`${selected.length} 项已选`:'不限';}
function buildBuckets(){const grouped=new Map();for(const item of state.items)for(const b of benchmarks(item)){const key=benchmarkKey(b);if(b.isPrimary===false||!key)continue;let bucket=grouped.get(key);if(!bucket){bucket={key,label:benchmarkLabel(b),params:stableParams(b.parameters),min:b.score,max:b.score,scores:0,itemIds:new Set()};grouped.set(key,bucket);}bucket.min=Math.min(bucket.min,b.score);bucket.max=Math.max(bucket.max,b.score);bucket.scores++;bucket.itemIds.add(item.itemId);}state.buckets=[...grouped.values()].sort((a,b)=>a.label.localeCompare(b.label,'zh-CN'));for(const b of state.buckets)state.scoreRanges[b.key]={min:b.min,max:b.max};}
function renderScoreRanges(){const selected=state.multi.benchmark;$('score-ranges').innerHTML=state.buckets.filter(b=>selected.includes(b.key)).map((b,index)=>{const r=state.scoreRanges[b.key];const unique=b.min===b.max;return `<section class="score-range" data-score-key="${escapeHTML(b.key)}"><h4>${escapeHTML(b.label)}</h4>${b.params?`<p class="filter-note">参数：${escapeHTML(b.params)}</p>`:''}<div class="score-numbers"><label>最低值<input type="number" step="any" min="${b.min}" max="${b.max}" value="${r.min}" data-score-bound="min" data-score-key="${escapeHTML(b.key)}" aria-label="${escapeHTML(b.label)}最低分"></label><span>至</span><label>最高值<input type="number" step="any" min="${b.min}" max="${b.max}" value="${r.max}" data-score-bound="max" data-score-key="${escapeHTML(b.key)}" aria-label="${escapeHTML(b.label)}最高分"></label></div><div class="dual-range" style="--lo:${unique?0:(r.min-b.min)/(b.max-b.min)*100}%;--hi:${unique?100:(r.max-b.min)/(b.max-b.min)*100}%"><div class="range-track"></div><input type="range" min="${b.min}" max="${b.max}" step="any" value="${r.min}" data-score-bound="min" data-score-key="${escapeHTML(b.key)}" aria-label="拖动${escapeHTML(b.label)}最低分" ${unique?'disabled':''}><input type="range" min="${b.min}" max="${b.max}" step="any" value="${r.max}" data-score-bound="max" data-score-key="${escapeHTML(b.key)}" aria-label="拖动${escapeHTML(b.label)}最高分" ${unique?'disabled':''}></div><p class="filter-note">可用 ${b.min}–${b.max} · ${b.itemIds.size} 条对象${unique?' · 仅一个分值':''} · 含区间端点</p></section>`;}).join('');}
function normalizeScoreRange(bucket,range,bound,input){const n=Number(input);if(!Number.isFinite(n))return {...range};const value=Math.max(bucket.min,Math.min(bucket.max,n));return bound==='min'?{min:Math.min(value,range.max),max:range.max}:{min:range.min,max:Math.max(value,range.min)};}
function updateScore(target){const key=target.dataset.scoreKey,bound=target.dataset.scoreBound,bucket=state.buckets.find(b=>b.key===key);if(!bucket)return;state.scoreRanges[key]=normalizeScoreRange(bucket,state.scoreRanges[key],bound,target.value);const r=state.scoreRanges[key];for(const el of document.querySelectorAll('[data-score-bound]'))if(el.dataset.scoreKey===key)el.value=r[el.dataset.scoreBound];const section=target.closest('.score-range');if(section){const track=section.querySelector('.dual-range'),span=bucket.max-bucket.min;track.style.setProperty('--lo',`${span?(r.min-bucket.min)/span*100:0}%`);track.style.setProperty('--hi',`${span?(r.max-bucket.min)/span*100:100}%`);}state.page=1;render();}
function clearFilter(key){if(multiFields.includes(key)){state.multi[key]=[];for(const node of document.querySelectorAll(`[data-multi="${key}"]`))node.checked=false;updateMultiSummary(key);if(key==='benchmark'){for(const b of state.buckets)state.scoreRanges[b.key]={min:b.min,max:b.max};renderScoreRanges();}}else if($(key))$(key).value='';refresh();}
function reset(){resetWorkbench();for(const id of numericFields)$(id).value='';for(const id of multiFields){state.multi[id]=[];for(const node of document.querySelectorAll(`[data-multi="${id}"]`))node.checked=false;updateMultiSummary(id);}for(const b of state.buckets)state.scoreRanges[b.key]={min:b.min,max:b.max};$('query').value='';for(const input of document.querySelectorAll('[data-search-options]'))input.value='';for(const label of document.querySelectorAll('[data-option-label]'))label.hidden=false;renderScoreRanges();refresh();}
function refresh(){state.page=1;const currencies=state.multi.currency,periods=state.multi.period;const canPrice=currencies.length===1&&periods.length===1&&currencies[0]!=='unknown'&&periods[0]!=='unknown';$('maxPrice').disabled=!canPrice;if(!canPrice)$('maxPrice').value='';render();}
function filterChipLabel(key,f){if(['cpu','memory','disk'].includes(key))return (f[key+'Op']||'>')+' '+f[key];if(multiFields.includes(key))return asArray(f[key]).map(v=>state.optionLabels[key]?.[v]||v).join('、');return f[key];}
function render(){const f=currentFilters(),q=$('query').value.trim(),active=fields.filter(k=>filterActive(f,k)),hasFilters=active.length>0||workbenchFiltersActive();state.filtered=state.mode==='items'?state.items.filter(i=>matchItem(i,f,q)):state.posts.filter(p=>{const postMatch=!q||[p.label,p.postId,p.sourceUrl,p.summary].join(' ').toLowerCase().includes(q.toLowerCase());if(!hasFilters)return postMatch||p.items.some(i=>matchItem(i,f,q));return p.items.some(i=>matchItem(i,f,postMatch?'':q));});const pages=Math.max(1,Math.ceil(state.filtered.length/state.pageSize));state.page=Math.min(state.page,pages);$('results-title').innerHTML=`${state.mode==='items'?'测试对象':'原帖'} <span id="result-count">${state.filtered.length}</span>`;$('result-context').textContent=state.mode==='items'?`来自 ${new Set(state.filtered.map(i=>i.postId)).size} 篇原帖`:`含 ${state.filtered.reduce((sum,p)=>sum+p.items.length,0)} 条对象 / 套餐`;$('type-summary').textContent=state.mode==='items'?'硬件比较符可见；分类同组任一、跨组同时满足':'工具、补货与报告链接资料也在这里，不补造测试对象';$('mode-items').setAttribute('aria-pressed',state.mode==='items');$('mode-posts').setAttribute('aria-pressed',state.mode==='posts');$('active-filters').hidden=!active.length&&!q;$('active-filters').innerHTML=(q?`<button class="chip" data-clear="query">搜索：${escapeHTML(q)} ×</button>`:'')+active.map(k=>`<button class="chip" data-clear="${k}">${escapeHTML(filterNames[k])}：${escapeHTML(filterChipLabel(k,f))} ×</button>`).join('');$('mobile-filters').textContent=active.length?`筛选 · ${active.length}`:'筛选条件';const entries=state.filtered.slice((state.page-1)*state.pageSize,state.page*state.pageSize);$('result-list').innerHTML=entries.length?(state.mode==='items'?compactRecords(entries):entries.map(postCard).join('')):'<div class="empty"><strong>没有匹配的记录</strong><p>试试减少条件。未知配置和缺失跑分不会作为零值匹配。</p><button class="button" data-reset>清空筛选，查看全部</button></div>';$('pagination').innerHTML=state.filtered.length>state.pageSize?`<button data-page="${state.page-1}" ${state.page===1?'disabled':''}>上一页</button>${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" ${state.page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button data-page="${state.page+1}" ${state.page===pages?'disabled':''}>下一页</button><span class="page-label">${(state.page-1)*state.pageSize+1}–${Math.min(state.page*state.pageSize,state.filtered.length)} / ${state.filtered.length}</span>`:'';refreshWorkbenchBadges();}
function fact(label,value){return `<div class="fact"><span>${escapeHTML(label)}</span><strong>${escapeHTML(text(value))}</strong></div>`;}
function notes(value,cls='evidence-line'){return value?`<p class="${cls}">${escapeHTML(value)}</p>`:'';}
function sourceLink(item){return `<a class="detail-source" href="${escapeHTML(safeSource(item.sourceUrl))}" target="_blank" rel="noopener noreferrer">查看 NodeSeek 原帖 · #${escapeHTML(item.postId)}</a>`;}
function availability(post){const a=post.evidenceAvailability||{};return `<p class="detail-note">采集时读取到 ${a.downloadedImageReferencesAtCollection??'未知'} 张图片，另有 ${a.unavailableImageReferencesAtCollection??'未知'} 张未能读取。本站不展示或加载原图，缺图可能影响事实覆盖。</p>`;}
function warnings(post){return post.warnings?.length?`<section class="detail-section"><h3>阅读提醒</h3><ul class="warning-list">${post.warnings.map(w=>`<li>${escapeHTML(w)}</li>`).join('')}</ul>${availability(post)}</section>`:`<section class="detail-section"><h3>资料覆盖</h3>${availability(post)}</section>`;}
function timeReports(item){const ts=item.testedAt||{};const reports=ts.reports?.length?ts.reports:(ts.primary?.raw?[ts.primary]:[]);return reports.length?`<div class="report-list">${reports.map((r,k)=>`<div class="report"><strong>${escapeHTML(r.phase||r.kind||`报告 ${k+1}`)}</strong><p>原始时间：${escapeHTML(text(r.raw))}</p><p>原时区：${escapeHTML(r.timezone||'未确认')}${r.beijing?`<br>北京时间：${escapeHTML(r.beijing.replace('T',' ').replace('+08:00',''))}`:' · 不换算北京时间'}</p>${r.scriptVersion||r.script_version?`<p>脚本版本：${escapeHTML(r.scriptVersion||r.script_version)}</p>`:''}${r.scope?`<p>${escapeHTML(r.scope)}</p>`:''}</div>`).join('')}</div>`:'<p class="detail-note">测试时间未知。未用发帖时间替代，也未从其他配置阶段补入。</p>';}
function itemDetail(item){const c=item.configuration||{},loc=item.location||{},p=primaryPrice(item)||item.price||{},quota=item.trafficQuota||{},n=item.network||{},post=state.posts.find(p=>p.postId===item.postId);return `${badge(item)}<h2 id="detail-title">${escapeHTML(item.label)}</h2>${sourceLink(item)}<p class="detail-summary">${escapeHTML(item.summary)}</p><section class="detail-section"><h3>硬件配置</h3><div class="fact-grid">${fact('CPU 核数',c.vcpu==null?null:`${c.vcpu} 核`)}${fact('内存',capacityText(c.memoryValue,c.memoryUnit))}${fact('硬盘',capacityText(c.diskValue,c.diskUnit))}${fact('CPU 型号',c.cpuModel)}${fact('硬盘类型',getDiskType(item)||'未注明')}${fact('商家',item.vendor)}</div>${notes(c.basis?`配置依据：${c.basis}`:'配置依据未知。')}${c.reportedThreads!=null?notes(`报告线程数：${c.reportedThreads}`):''}${c.reportedCores!=null?notes(`报告核心数：${c.reportedCores}`):''}${c.physicalCores!=null?notes(`物理核心数：${c.physicalCores}`):''}</section><section class="detail-section"><h3>地点</h3><div class="fact-grid">${fact('来源中的产品地区',getLocation(item)||null)}</div>${notes(loc.basis?`依据：${loc.basis}`:'地区依据未知。')}${notes(loc.note)}</section><section class="detail-section"><h3>线路记录</h3><div class="route-tags">${routes(item)}</div>${n.routeObservations?.length?`<table class="route-table"><thead><tr><th>网络与方向</th><th>运营商 / 线路</th><th>标签依据与边界</th></tr></thead><tbody>${n.routeObservations.map(r=>`<tr><td>${escapeHTML(r.family||'IP 协议未注明')}<br>${escapeHTML(r.direction||'方向未注明')}</td><td>${escapeHTML(r.operator||'运营商未注明')}<br>${escapeHTML(r.label||'标签未知')}${r.otherLabels?.length?`<small>其他观测：${escapeHTML(r.otherLabels.join('、'))}</small>`:''}</td><td>${escapeHTML(r.basis||'依据未明确')}${r.evidenceType?`<small>${r.evidenceType==='author_claim'?'作者宣称':r.evidenceType==='measured_script_label'?'实读报告脚本标签':escapeHTML(r.evidenceType)}</small>`:''}${r.note?`<small>${escapeHTML(r.note)}</small>`:''}</td></tr>`).join('')}</tbody></table>`:'<p class="detail-note">没有可读的三网去程 / 回程明细，不推断完整线路。</p>'}${notes(n.note)}</section>${benchmarkDetails(item)}${priceDetails(item)}<section class="detail-section"><h3>流量与带宽</h3><div class="fact-grid">${fact('流量额度',quota.value==null?null:`${quota.value} ${quota.unit||'单位未知'}`)}${fact('流量统计方向',quota.direction)}${fact('流量重置周期',quota.period)}</div>${notes(quota.note)}${item.bandwidthClaims?.length?notes('带宽宣称：'+item.bandwidthClaims.map(b=>[b.advertisedPortMbps!=null?`端口 ${b.advertisedPortMbps} Mbps`:null,b.unmeteredMbps!=null?`不限量 ${b.unmeteredMbps} Mbps`:null,b.advertisedMbps!=null?`标称 ${b.advertisedMbps} Mbps`:null,b.raw,b.note,b.basis].filter(Boolean).join('；')).filter(Boolean).join('。')):''}</section><section class="detail-section"><h3>测试与报告时间</h3>${timeReports(item)}<p class="detail-note">各模块时间独立保留；只对已确认时区的记录显示北京时间。</p></section>${skillReviewDetails(item)}${imageEvidenceDetails(item)}${warnings(post)}<section class="detail-section"><h3>来源</h3>${notes(item.evidence?.basis)}${sourceLink(item)}<p class="detail-note">资料整理于 ${escapeHTML(post?.addedOn||'2026-10-05')}；这是历史快照，未核验当前库存、报价或线路表现。</p></section>`;}
function postDetail(post){return `<span class="badge">${escapeHTML(categoryLabels[post.category]||post.category)}</span><h2 id="detail-title">${escapeHTML(post.label)}</h2>${sourceLink(post)}<p class="detail-summary">${escapeHTML(post.summary)}</p><section class="detail-section"><h3>${post.items.length?`本帖 ${post.items.length} 条对象 / 套餐`:'资料帖'}</h3>${post.items.length?`<div class="detail-items">${post.items.map(i=>`<button class="detail-item" data-detail="item:${escapeHTML(i.itemId)}">${escapeHTML(i.label)}<small>${escapeHTML(typeLabels[i.itemType])}</small></button>`).join('')}</div>`:'<p class="detail-note">本帖没有可单列的 VPS 测试对象。工具和外部报告链接保留为资料，不计入 VPS 实测记录。</p>'}</section>${warnings(post)}`;}
function openDetail(key){state.detailFromApp=true;location.hash=encodeURIComponent(key);}
function closeDetail(){history.replaceState(null,'',location.pathname+location.search);syncDetail();}
function syncDetail(){let key='';try{key=decodeURIComponent(location.hash.slice(1));}catch{}const [type,id]=key.split(':');const record=type==='item'?state.items.find(i=>i.itemId===id):type==='post'?state.posts.find(p=>p.postId===id):null;if(!record){if($('detail-dialog').open)$('detail-dialog').close();return;}$('detail-content').innerHTML=type==='item'?itemDetail(record):postDetail(record);if(!$('detail-dialog').open)$('detail-dialog').showModal();$('detail-dialog').scrollTop=0;}
function priceText(p){if(p?.monthlyQuote!=null)return `${escapeHTML(p.currency||'币种未知')} ${escapeHTML(p.monthlyQuote)} <small>/ 月报价 · 账期${p.billingPeriod?escapeHTML(periodLabels[p.billingPeriod]||p.billingPeriod):'未知'}</small>${String(p.currencyBasis||'').includes('默认')?'<span class="price-inferred">默认美元</span>':''}`;if(p&&isKnownNumber(p.amount)&&p.currency)return `${escapeHTML(p.currency)} ${escapeHTML(p.amount)} <small>${p.billingPeriod?`/ ${escapeHTML(periodLabels[p.billingPeriod]||p.billingPeriod)}`:'· 周期未知'}</small>${p.priceKind&&p.priceKind!=='unspecified'?`<small> · ${escapeHTML(priceKindLabels[p.priceKind]||p.priceKind)}</small>`:''}${String(p.currencyBasis||'').includes('默认')?'<span class="price-inferred">默认美元</span>':''}`;if(p?.raw)return `<span>${escapeHTML(p.raw)}</span><small> · 金额 / 币种未确认</small>`;return '<span class="unknown">价格未知</span>';}
function scoreCard(item){const all=benchmarks(item).filter(b=>b.isPrimary!==false),selected=state.multi.benchmark,matching=selected.length?all.filter(b=>selected.includes(benchmarkKey(b))):all;return matching.length?`<div class="score-card">${matching.slice(0,2).map(b=>`<span>${escapeHTML(benchmarkLabel(b))} <strong>${escapeHTML(b.score)}</strong>${b.phase?`<small> ${escapeHTML(b.phase)}</small>`:''}</span>`).join('')}${matching.length>2?`<span class="score-more">另 ${matching.length-2} 条，见详情</span>`:''}</div>`:'';}
function benchmarkDetails(item){const rows=benchmarks(item);return `<section class="detail-section"><h3>CPU 跑分</h3>${rows.length?`<div class="benchmark-detail-grid">${rows.map(b=>`<article class="benchmark-evidence"><span class="eyebrow">${escapeHTML(benchmarkLabel(b))}</span><strong class="benchmark-value">${escapeHTML(b.score)}<small>${escapeHTML(b.unit||'单位未注明')}</small></strong>${b.fullVersion?notes(`完整版本：${b.fullVersion}`):''}${b.phase?notes(`阶段：${b.phase==='reported'?'原帖报告':b.phase}${b.isPrimary===false?' · 历史对照，不参与滑块':' · 主观测'}`):''}${b.testTime?notes(`测试时间：${typeof b.testTime==='object'?b.testTime.raw||'未知':b.testTime}`):''}${b.testTime&&typeof b.testTime==='object'?notes(`原时区：${b.testTime.timezone||'未确认，不换算北京时间'}`):''}${notes(b.note)}${stableParams(b.parameters)?notes(`参数：${stableParams(b.parameters)}`):''}${notes(typeof b.evidence==='object'?b.evidence.summary||b.evidence.basis||JSON.stringify(b.evidence):b.evidence||b.basis)}${notes(benchmarkKey(b)&&b.isPrimary!==false?'该分数可在对应版本与指标桶内筛选。':'历史对照或版本 / 参数不完整，仅供查看，不参与区间筛选。','detail-note')}</article>`).join('')}</div>`:'<p class="detail-note">没有可核对的 CPU 跑分。缺图或原帖未披露时不补值，不用其他机器或阶段的分数替代。</p>'}<p class="detail-note">历史复测分别保留。滑块仅筛各对象标记的主观测，不挑最高分；主观测也不代表当前表现。</p></section>`;}
function priceDetails(item){const rows=priceRecords(item);return `<section class="detail-section"><h3>历史价格 · 逐条依据</h3><div class="price-observations">${rows.map(p=>`<article class="price-evidence"><div class="price-main">${priceText(p)}</div><div class="fact-grid">${fact('原始价格表述',p.raw)}${fact('价格类型',priceKindLabels[p.priceKind]||p.priceKind)}${fact('币种识别依据',typeof p.currencyBasis==='object'?JSON.stringify(p.currencyBasis):p.currencyBasis)}</div>${notes(typeof p.evidence==='object'?p.evidence.summary||p.evidence.basis||JSON.stringify(p.evidence):p.evidence)}${notes(p.note)}</article>`).join('')}</div><p class="detail-note">明确写出的币种按原文；刀按美元，数值旁 O/o/欧按欧元，明确价格没有币种时默认美元。周期未知不折算月均，转让与开通费不进入周期价格上限。</p></section>`;}
async function loadCatalogSnapshot(){const response=await fetch('./catalog-snapshot.json',{cache:'no-store'});if(response.status===404)return null;if(!response.ok)throw new Error('catalog snapshot unavailable');const payload=await response.json();if(payload.schemaVersion!=='vps-catalog-snapshot/1'||!payload.files||!['data.json','enrichment.json','filter-spec.json','image-evidence.json','skill-refresh.json'].every(name=>payload.files[name]&&typeof payload.files[name]==='object'))throw new Error('invalid catalog snapshot');return payload.files;}
async function init(){try{
 const catalogFiles=await loadCatalogSnapshot();const fetchCatalog=path=>catalogFiles?Promise.resolve({ok:true,json:async()=>catalogFiles[path.replace(/^\.\//,'')]}):fetch(path);
 const response=await fetchCatalog('./data.json');if(!response.ok)throw new Error('data unavailable');state.data=await response.json();state.posts=state.data.posts;state.items=state.posts.flatMap(p=>p.items);
 const extraResponse=await fetchCatalog('./enrichment.json');if(!extraResponse.ok)throw new Error('enrichment unavailable');const extra=await extraResponse.json();const known=new Map(state.items.map(i=>[i.itemId,i]));for(const row of extra.entries||[]){const item=known.get(row.itemId);if(item&&(!row.postId||String(row.postId)===String(item.postId))){item.priceObservations=row.priceObservations||[];item.cpuBenchmarks=row.cpuBenchmarks||[];}}
 const [specData,imageData,skillData]=await Promise.all([fetchCatalog('./filter-spec.json').then(r=>{if(!r.ok)throw new Error('spec unavailable');return r.json();}),fetchCatalog('./image-evidence.json').then(r=>{if(!r.ok)throw new Error('image evidence unavailable');return r.json();}),fetchCatalog('./skill-refresh.json').then(r=>{if(!r.ok)throw new Error('skill refresh unavailable');return r.json();})]);applySkillRefresh(skillData);$('pipeline-management').hidden=skillData.pipelineIntegration?.managementPath!=='/';setupWorkbench(specData,imageData);
 $('post-total').textContent=state.posts.length;$('item-total').textContent=state.items.length;$('mode-items').innerHTML=`测试对象 <span>${state.items.length}</span>`;$('mode-posts').innerHTML=`原帖 <span>${state.posts.length}</span>`;$('method-catalog-count').textContent=`${state.posts.length} 篇原帖，${state.items.length} 条对象`;$('method-object-types').textContent=Object.entries(typeLabels).map(([type,label])=>`${state.items.filter(i=>i.itemType===type).length} 条${label}`).join('、')+'。复测和不同阶段可能属于同一机器；资料帖不补造测试对象。';
 const sorted=values=>[...new Set(values.filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'));
 multiControl('itemType',Object.entries(typeLabels).map(([value,label])=>({value,label})));
 multiControl('vendor',sorted(state.items.map(i=>i.vendor)),true);
 multiControl('cpuModel',sorted(state.items.map(i=>i.configuration.cpuModel)),true);
 multiControl('diskType',sorted(state.items.map(getDiskType)),true);
 multiControl('country',sorted(state.items.map(i=>i.location?.country)),true);
 multiControl('city',sorted(state.items.map(getFilterCity)),true);
 multiControl('route',sorted(state.items.flatMap(i=>i.network.filterRouteTags)),true);
 multiControl('routeSource',[{value:'reported',label:'报告中的线路标签'},{value:'claimed',label:'商品 / 作者宣称'}]);
 multiControl('currency',sorted(state.items.flatMap(i=>priceRecords(i).map(p=>p.currency))),true);
 multiControl('period',sorted(state.items.flatMap(i=>priceRecords(i).map(p=>p.billingPeriod))).map(value=>({value,label:(periodLabels[value]||value)+'付'})),true);
 multiControl('priceKind',sorted(state.items.flatMap(i=>priceRecords(i).filter(p=>p.filterEligible!==false).map(p=>p.priceKind))).map(value=>({value,label:priceKindLabels[value]||value})));
 buildBuckets();multiControl('benchmark',state.buckets.map(b=>({value:b.key,label:`${b.label} (${b.itemIds.size})`})));renderScoreRanges();
 const covered=state.items.filter(i=>benchmarks(i).length).length,filterable=state.items.filter(i=>benchmarks(i).some(b=>b.isPrimary!==false&&benchmarkKey(b))).length;$('score-coverage').textContent=`${covered} 条对象有可读跑分，${filterable} 条可作版本内筛选；共 ${state.buckets.length} 个独立桶。`;
 for(const id of numericFields)$(id).addEventListener('input',refresh);$('query').addEventListener('input',refresh);
 $('mode-items').onclick=()=>{state.mode='items';refresh();};$('mode-posts').onclick=()=>{state.mode='posts';refresh();};$('filters').onsubmit=e=>e.preventDefault();
 $('mobile-filters').onclick=()=>{const open=$('filter-panel').classList.toggle('open');$('mobile-filters').setAttribute('aria-expanded',String(open));};
 document.addEventListener('change',e=>{const target=e.target;if(target.dataset.multi){const id=target.dataset.multi;state.multi[id]=[...document.querySelectorAll(`[data-multi="${id}"]:checked`)].map(el=>el.value);updateMultiSummary(id);if(id==='benchmark')renderScoreRanges();refresh();}});
 document.addEventListener('input',e=>{const t=e.target;if(t.dataset.searchOptions){const list=$(t.dataset.searchOptions);for(const label of list.querySelectorAll('[data-option-label]'))label.hidden=!label.dataset.optionLabel.includes(t.value.toLowerCase());}if(t.dataset.scoreBound)updateScore(t);});
 document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.hasAttribute('data-reset'))reset();if(target.dataset.clear)clearFilter(target.dataset.clear);if(target.dataset.detail)openDetail(target.dataset.detail);if(target.dataset.page){state.page=Number(target.dataset.page);render();$('results').scrollIntoView({behavior:'smooth',block:'start'});}});
 $('detail-close').onclick=closeDetail;$('detail-dialog').addEventListener('cancel',e=>{e.preventDefault();closeDetail();});$('detail-dialog').addEventListener('click',e=>{if(e.target===$('detail-dialog')){const r=$('detail-dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDetail();}});
 $('method-open').onclick=()=>$('method-dialog').showModal();$('method-close').onclick=()=>$('method-dialog').close();document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('query').focus();}});
 window.addEventListener('hashchange',syncDetail);completeWorkbench();render();syncDetail();refreshScopeBanner();window.__catalog={state,matchItem,capacity,getDiskType,strictGreater,priceRecords,parsePriceText,benchmarkKey,normalizeScoreRange};
 }catch(error){$('result-list').innerHTML='<div class="empty"><strong>资料暂时没有加载成功</strong><p>请刷新页面重试。缺失数据不会用示例分数替代。</p><button class="button" id="catalog-retry">重新加载</button></div>';$('catalog-retry').addEventListener('click',()=>location.reload());console.error(error);}}
init();
